    const result = await runInit({ cwd: f.cwd, command: f.command, env: { NEATLOGS_API_KEY: 'fake-key' }, print: () => {}, doctor: async () => [],
      onboarding: async ({ config }) => { config.integrations.neatlogs = true; },
