  print('Integrations:');
  for (const [name, label] of [['neatlogs', 'Neatlogs'], ['entire', 'Entire'], ['cfoai', 'cfo.ai']] as const) {
    print(`  ${label.padEnd(18)} ${config.integrations[name] ? 'on' : 'off'}`);
